---RefreshBoardByContent 根据标题和内容刷新提示板
---@param titleText string 标题文字
---@param contentText string 内容文字
---@param descText string 一段描述
---@param rare number
---@param id number 物品id
---@param isShowNumText boolean 是否显示数量
function CommonActivityStaminaTipsCountdown:RefreshBoardByContent(titleText, contentText, rare, id ,isShowNumText, descText)
	self.goodsId = id
	-- 标题
	local env = CfUtils.GetLuaScr(self.TitleNode.gameObject, TitleNodePath)
	if isNotNull(env) then
		---@type CommonTitleNode
		env:RefreshUI(titleText, rare)
	end
	local descTitle = not string.isEmpty(contentText) and string.gsub(contentText, "\\n", "\n") or ""
	CfUtils.FillText(self.TitleTxt, descTitle)
	if not string.isEmpty(descText) then
		CfUtils.FillText(self.ContentTxt, descText)
	else
		---@type GoodsVo
		local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
		if goodsVo then
			if string.isEmpty(goodsVo.description) then
				KTool.SetActive(self.ContentTxt, false)
			else
				CfUtils.FillText(self.TitleTxt, goodsVo.description)     --物品的直接强转
				CfUtils.FillText(self.ContentTxt, goodsVo.desc)
				KTool.SetActive(self.ContentTxt, true)
			end
		else
			KTool.SetActive(self.ContentTxt, false)
		end
	end
	KTool.SetActive(self.NumTxt, isShowNumText ~= nil and isShowNumText or false)
	KTool.SetActive(self.TextNumber, isShowNumText ~= nil and isShowNumText or false)
	if id ~= nil and isShowNumText == true then
		self:SetItemNum(id)
	end
	self:InitRootDesc(id)
	self:RefreshCountDown(id)
	self:UpdateGoodsImg(id)
end

function CommonActivityStaminaTipsCountdown:UpdateGoodsImg(id)
	local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
	if isNull(goodsVo) then
		CfUtils.SetActive(self.GoodNode, false)
		return
	end
	local ctrl = CfUtils.GetLuaScr(self.GoodNode.gameObject, "Game.Behaviours.GoodNodeMB")
	--ctrl:FillGoodsStarInfo(id)
	ctrl:Reload({
		goodsId = id,
		isShowNo = false
	})
	self:FillGoodsStarInfo(id)
end

function CommonActivityStaminaTipsCountdown:FillGoodsStarInfo(goodsId)
	if isNull(self.StarGroup) then
		return
	end
	if checkNumber(goodsId) <= 0 then
		return
	end
	local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
	if not goodsVo then
		return
	end
	local vo = CfUtils.GetCfVo(AutoIds.IdSetting4070, "GoodsShowTypeVo", goodsVo.showType)
	local isShowStar = false
	if vo then
		isShowStar = (checkNumber(vo.showStar) == 1)
	end
	CfUtils.SetActive(self.StarGroup, isShowStar)
	if isShowStar then
		local num = checkNumber(goodsVo.quality)
		for i = 1, num do
			local go = self.StarGroup.transform:Find("go"..i)
			if isNull(go) then
				go = CfUtils.InstantiateGo(self.ImgStar, self.StarGroup)
				go.name = "go"..i
			end
			CfUtils.SetActive(go, true)
		end
		
		if num + 1 < self.StarGroup.transform.childCount then
			for i = num + 1, self.StarGroup.transform.childCount do
				local go = self.StarGroup.transform:Find("go"..i)
				CfUtils.SetActive(go, false)
			end
		end
	end
end

function CommonActivityStaminaTipsCountdown:SetItemNum(id)
	local amount = checkInt(self:GetGoodsNum(id))
	CfUtils.FillText(self.TextNumber, amount)
end

function CommonActivityStaminaTipsCountdown:RefreshCountDown(goodsId)
	if isNull(self.playerDojo) then return end
	local hpMax = self:GetGoodsLimit(self.goodsId)
	local goodsNum = self:GetGoodsNum(self.goodsId)
	self.TextHPDesc.text = self:GetGoodRecoverDesc(self.goodsId)
	local nextHpSeconds = self:GetNextRecoveryTime(self.goodsId)
	if (goodsNum >= hpMax) and nextHpSeconds <= 0 then
		self:SetHPFull()
	else
		self:SetTimeDown()
	end
end

function CommonActivityStaminaTipsCountdown:SetHPFull()
	local value = CfUtils.GetTimeHMS(0)
	CfUtils.FillText(self.TextHPNext_Time, value)
	local descFullHP = localize("恢复已满")
	CfUtils.FillText(self.TextHPWhole_Time, descFullHP)
end

function CommonActivityStaminaTipsCountdown:SetTimeDown()
	if not IsNull(self.timer) then
		CDTimerModule.GetInstance():RemoveCD(self.timer)
		self.timer = nil
	end
	
	local leftTime = self:GetNextRecoveryTime(self.goodsId)
	if isNull(self.playerDojo) then return end
	local hpMax = self:GetGoodsLimit(self.goodsId)
	local goodsNum = self:GetGoodsNum(self.goodsId)
	self:SetTxtValueTimer(leftTime, hpMax, goodsNum)
	
	self.timer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
		if count <= 0 then
			if self.timer then
				CDTimerModule.GetInstance():RemoveCD(self.timer)
				self.timer = nil
				local _hpMax = self:GetGoodsLimit(self.goodsId)
				local _goodsNum = self:GetGoodsNum(self.goodsId)
				if (_goodsNum >= _hpMax) then
					self:SetHPFull()
				else
					self:SetItemNum(self.goodsId)
					self:SetTimeDown()
				end
			end
		else
			self:SetTxtValueTimer(count, hpMax, goodsNum)
		end
	end, math.abs(leftTime), false, true, true)
end

function CommonActivityStaminaTipsCountdown:SetTxtValueTimer(leftTime, hpMax, goodsNum)
	local valuePre = CfUtils.GetTimeHMS(leftTime)
	local hpRecoverSeconds = self:GetGoodRecoverSeconds(self.goodsId)
	CfUtils.FillText(self.TextHPNext_Time, valuePre)
	local valueWhole = self:TimeFormat(checkInt(leftTime + (hpMax - goodsNum - 1) * checkInt(hpRecoverSeconds)))
	CfUtils.FillText(self.TextHPWhole_Time, valueWhole)
end

